import sys

def determine_winner(s):
    n = len(s)
    winners = []

    # Precompute the next smaller element to the left and right for each character
    left_next_smaller = [-1] * n
    right_next_smaller = [n] * n

    stack = []
    for i in range(n):
        while stack and s[stack[-1]] > s[i]:
            right_next_smaller[stack.pop()] = i
        if stack:
            left_next_smaller[i] = stack[-1]
        stack.append(i)

    # Determine the winner for each k
    for k in range(n):
        if left_next_smaller[k] == -1 and right_next_smaller[k] == n:
            winners.append("Mike")
        else:
            winners.append("Ann")

    return winners

def main():
    import sys
    s = sys.stdin.read().strip()
    winners = determine_winner(s)
    for winner in winners:
        print(winner)

if __name__ == "__main__":
    main()
